// A.1 — RAPPORT DES VENTES
// Calcul du chiffre d'affaires total et du panier moyen
// Toutes les valeurs sont calculées après remises

// 1. Récupérer les données des deux API
const donnees = $input.all().map(item => item.json);

// 2. Identifier les paniers et le taux de change
const ventes = donnees.find(d => Array.isArray(d.carts));
const change = donnees.find(d => d.rates?.EUR !== undefined);

// 3. Vérifier la disponibilité des données
if (!ventes || !change) {
  throw new Error("Données des ventes ou taux de change manquants");
}

// 4. Récupérer les paniers et le taux EUR
const paniers = ventes.carts;
const taux = Number(change.rates.EUR);

// 5. Vérifier que tous les paniers ont été récupérés
if (paniers.length !== ventes.total) {
  throw new Error(
    `Données incomplètes : ${paniers.length} paniers reçus sur ${ventes.total}`
  );
}

// 6. Vérifier le taux de change
if (!Number.isFinite(taux) || taux <= 0) {
  throw new Error("Taux de change EUR invalide");
}

// 7. Calculer le chiffre d'affaires total USD après remises
const ca_usd = paniers.reduce(
  (somme, panier) => somme + Number(panier.discountedTotal),
  0
);

// 8. Vérifier le chiffre d'affaires
if (!Number.isFinite(ca_usd)) {
  throw new Error("Chiffre d'affaires invalide");
}

if (paniers.length === 0) {
  throw new Error("Aucun panier disponible");
}

// 9. Convertir le chiffre d'affaires en EUR
const ca_eur = ca_usd * taux;

// 10. Calculer le nombre de paniers et le panier moyen
const nombre_paniers = paniers.length;
const panier_moyen = ca_eur / nombre_paniers;

// 11. Retourner le rapport des ventes
return [{
  json: {
    nombre_paniers: nombre_paniers,
    ca_total_usd: Number(ca_usd.toFixed(2)),
    taux_change: taux,
    date_taux: change.date,
    ca_total_eur: Number(ca_eur.toFixed(2)),
    panier_moyen_eur: Number(panier_moyen.toFixed(2))
  }
}];

// A.1 — TOP 5 PRODUCTS BY QUANTITY SOLD
// Input: Shopping carts (USD) + USD/EUR exchange rate
// Output: 5 products with quantity and discounted revenue in EUR

// 1. Retrieve data from both APIs
const data = $input.all().map(item => item.json);

// 2. Identify shopping carts and exchange rate
const sales = data.find(d => Array.isArray(d.carts));
const exchange = data.find(d => d.rates?.EUR !== undefined);

// 3. Validate input data
if (!sales || !exchange) {
  throw new Error("Missing shopping carts or USD/EUR exchange rate");
}

const carts = sales.carts;
const rate_eur = Number(exchange.rates.EUR);

if (carts.length !== sales.total) {
  throw new Error(
    `Incomplete data: received ${carts.length} of ${sales.total} carts`
  );
}

if (!Number.isFinite(rate_eur) || rate_eur <= 0) {
  throw new Error("Invalid EUR exchange rate");
}

// 4. Aggregate products by product ID
const products = {};

for (const cart of carts) {
  for (const product of cart.products) {

    const id = product.id;

    if (!products[id]) {
      products[id] = {
        product: product.title,
        quantity: 0,
        revenue_usd: 0
      };
    }

    // Accumulate quantities
    products[id].quantity += Number(product.quantity);

    // Accumulate revenue after discounts
    products[id].revenue_usd += Number(product.discountedTotal);
  }
}

// 5. Sort products by quantity sold (descending)
// Keep only the five best-selling products
const top5 = Object.values(products)
  .sort((a, b) => b.quantity - a.quantity)
  .slice(0, 5);

// 6. Convert revenue to EUR
// Return 5 separate items for the CSV node
return top5.map(product => ({
  json: {
    product: product.product,
    quantity: product.quantity,
    revenue_eur: Number(
      (product.revenue_usd * rate_eur).toFixed(2)
    )
  }
}));

// A.1 — RAPPORT DE VENTES : SYNTHÈSE TEXTUELLE

// 1. Retrieve calculated sales indicators
const data = $input.first().json;

// 2. Format EUR amounts
const euros = (value) =>
  new Intl.NumberFormat("fr-BE", {
    style: "currency",
    currency: "EUR",
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  }).format(Number(value));

// 3. Format the exchange-rate date
const date = data.date_taux.split("-").reverse().join("/");

// 4. Build the report
const rapport = `
RAPPORT DES VENTES

Chiffre d'affaires total après remises :
${euros(data.ca_total_eur)}

Nombre de paniers :
${data.nombre_paniers}

Panier moyen :
${euros(data.panier_moyen_eur)}

TAUX DE CHANGE

1 USD = ${data.taux_change} EUR
Date du taux : ${date}

Les montants sont exprimés en euros,
après remises et arrondis à deux décimales.
`.trim();

// 5. Return the report
return [{
  json: {
    rapport_texte: rapport
  }
}];

// A.1 — Construct one validated payload for Nemotron (one request, not six).
const input = $input.all().map(item => item.json);
const sales = input.find(x => Number.isFinite(Number(x.nombre_paniers)) && x.ca_total_eur !== undefined);
const top5 = input.filter(x => typeof x.product === 'string' && x.quantity !== undefined && x.revenue_eur !== undefined);
if (!sales) throw new Error('Sales summary missing from merged input');
if (top5.length !== 5) throw new Error(`Expected 5 Top 5 products; received ${top5.length}`);
const mandatory = ['nombre_paniers','ca_total_usd','ca_total_eur','panier_moyen_eur','taux_change'];
for (const key of mandatory) {
  if (!Number.isFinite(Number(sales[key]))) throw new Error('Invalid field: ' + key);
}
if (!/^\d{4}-\d{2}-\d{2}$/.test(String(sales.date_taux))) throw new Error('Invalid exchange date');
if (Number(sales.nombre_paniers) <= 0) throw new Error('Number of carts must be positive');
if (Math.abs(Number((sales.ca_total_usd * sales.taux_change).toFixed(2)) - Number(sales.ca_total_eur)) > 0.011) {
  throw new Error('USD-to-EUR validation failed');
}
const products = top5.map(item => ({
  product: item.product,
  quantity: Number(item.quantity),
  revenue_eur: Number(item.revenue_eur)
}));
if (products.some(p => !Number.isFinite(p.quantity) || !Number.isFinite(p.revenue_eur))) {
  throw new Error('Invalid Top 5 numbers');
}
products.sort((a,b) => b.quantity-a.quantity || a.product.localeCompare(b.product));
const system = [
  'Tu es analyste commercial pour la direction. Réponds EXCLUSIVEMENT en français.',
  'Rédige UNIQUEMENT un commentaire analytique, pas le tableau des données.',
  'Structure : CONSTATS, INTERPRÉTATIONS, LIMITES, ACTIONS RECOMMANDÉES.',
  'Compare les quantités vendues et les revenus au sein du TOP 5 seulement.',
  'Propose deux actions concrètes vérifiables à partir des données manquantes.',
  'Ne présente aucune tendance temporelle, marge, rentabilité ou concentration du CA total sans données correspondantes.',
  'Ne confonds jamais chiffre d’affaires et bénéfice.',
  'IMPORTANT : N’utilise AUCUN CHIFFRE, numéro, montant, pourcentage ni devise dans ton texte : les indicateurs sont insérés séparément et sans IA.',
  'Ne recalcule aucune valeur. N’invente aucun fait. Evite le raisonnement intermédiaire.',
  'Longueur : environ 100 à 150 mots.'
].join(' ');
const data = {
  nombre_paniers: Number(sales.nombre_paniers),
  ca_total_eur: Number(sales.ca_total_eur),
  panier_moyen_eur: Number(sales.panier_moyen_eur),
  taux_usd_vers_eur: Number(sales.taux_change),
  date_taux: String(sales.date_taux),
  classement_top5_par_quantite: products
};
const ai_request = {
  model: 'veltis-llm',
  messages: [
    {role:'system',content:system},
    {role:'user',content: 'Voici les faits validés par le code. Analyse sans répéter les nombres :\n' + JSON.stringify(data)}
  ],
  max_tokens: 420,
  temperature: 0.2,
  stream: false,
  chat_template_kwargs: {enable_thinking: false}
};
return [{ json: {
  sent_at_utc: new Date().toISOString(),
  model_endpoint: 'http://172.21.0.1:8000/v1/chat/completions',
  model_max_context_tokens_last_verified: 2048,
  calculated_sales: sales,
  top5: products,
  ai_request
}}];

// A.1 — Assemble trusted financial results + AI-only interpretation;
// separately report token usage, generation parameters and quality warnings.
const response = $input.first().json || {};
const original = $('Prepare — Nemotron input').first().json;
const sales = original.calculated_sales;
const top5 = original.top5;
const choice = response.choices?.[0] ?? {};
const message = choice.message ?? {};
const raw = String(message.content ?? '');
const interpretation = raw.replace(/<think>[\s\S]*?<\/think>/gi,'').trim();
const usage = response.usage ?? {};
const endUtc = new Date().toISOString();
const elapsedMs = Math.max(0, Date.parse(endUtc) - Date.parse(original.sent_at_utc));
const decimals = (x) => new Intl.NumberFormat('fr-BE', {
  minimumFractionDigits:2, maximumFractionDigits:2
}).format(Number(x));
const euros = (x) => decimals(x) + ' EUR';
const warnings = [];
if (response.error) warnings.push('Nemotron HTTP request failed: ' + (typeof response.error === 'string' ? response.error : JSON.stringify(response.error)));
if (!interpretation) warnings.push('No final interpretation in the response');
if (/\d/.test(interpretation)) warnings.push('AI interpretation includes digits; verify any numerical claims');
if (/\b(?:USD|EUR)\b|\$|€/.test(interpretation)) warnings.push('AI interpretation includes a currency or currency symbol');
if (choice.finish_reason === 'length') warnings.push('Model stopped at max_tokens; commentary may be incomplete');
const hasReasoning = Boolean(message.reasoning || message.reasoning_content || /<think>/i.test(raw));
if (hasReasoning) warnings.push('Reasoning output detected; not included in diagnostic file');
if (response.model && response.model !== original.ai_request.model) warnings.push('Returned model ID does not match requested model');
const countCheck = Math.abs(Number(sales.panier_moyen_eur) * Number(sales.nombre_paniers) - Number(sales.ca_total_eur)) <= 0.011 * Number(sales.nombre_paniers);
if (!countCheck) warnings.push('Average-cart consistency check failed');
const commentary = (!interpretation || /\d|\b(?:USD|EUR)\b|\$|€|<think>/i.test(interpretation))
  ? 'Le commentaire automatique nécessite une vérification et n’a pas été repris dans le rapport. Consulter le fichier de diagnostic.'
  : interpretation;
const leaderQuantity = top5[0];
const leaderRevenue = [...top5].sort((a,b)=>b.revenue_eur-a.revenue_eur)[0];
const lines = [
  'RAPPORT DES VENTES — A.1',
  '',
  'INDICATEURS VALIDÉS (CALCULS JAVASCRIPT)',
  'Nombre de paniers : ' + sales.nombre_paniers,
  'Chiffre d’affaires total après remises : ' + euros(sales.ca_total_eur),
  'Panier moyen : ' + euros(sales.panier_moyen_eur),
  'Taux de change appliqué : 1 USD = ' + sales.taux_change + ' EUR',
  'Date du taux : ' + sales.date_taux,
  '',
  'TOP 5 DES PRODUITS — CLASSÉS PAR QUANTITÉ',
  ...top5.map((p,i) => `${i+1}. ${p.product} | ${p.quantity} unités | CA ${euros(p.revenue_eur)}`),
  '',
  'CONSTAT CALCULÉ : ' + leaderQuantity.product + ' domine les quantités au sein du Top 5 ; ' + leaderRevenue.product + ' domine les revenus au sein de ces cinq produits.',
  '',
  'COMMENTAIRE ANALYTIQUE NEMOTRON',
  commentary,
  '',
  'LIMITES : extraction de données factices ; absence de série temporelle, de coûts et de marges.',
  'NOTE : commentaire généré automatiquement ; validation humaine recommandée avant diffusion.'
];
const requested = original.ai_request;
const promptTokens = usage.prompt_tokens != null && Number.isFinite(Number(usage.prompt_tokens)) ? Number(usage.prompt_tokens) : null;
const completionTokens = usage.completion_tokens != null && Number.isFinite(Number(usage.completion_tokens)) ? Number(usage.completion_tokens) : null;
const totalTokens = usage.total_tokens != null && Number.isFinite(Number(usage.total_tokens)) ? Number(usage.total_tokens) : null;
const durationS = elapsedMs / 1000;
const metrics = {
  schema: 'A1-Nemotron-Usage-v1',
  run: {started_at_utc:original.sent_at_utc,finished_at_utc:endUtc,
        elapsed_end_to_end_seconds:Number(durationS.toFixed(3)),
        note:'Elapsed time includes n8n orchestration; not pure GPU inference time.'},
  model: {requested_id:requested.model,returned_id:response.model ?? null,
          engine:'vLLM',endpoint:original.model_endpoint,
          max_context_tokens_last_verified:original.model_max_context_tokens_last_verified},
  generation_settings: {temperature:requested.temperature,max_output_tokens:requested.max_tokens,
                        stream:requested.stream,thinking_requested:requested.chat_template_kwargs?.enable_thinking,
                        input_messages:requested.messages.length},
  usage: {prompt_tokens:promptTokens,completion_tokens:completionTokens,total_tokens:totalTokens,
          tokens_per_second_end_to_end_approx:(completionTokens !== null && durationS > 0)
            ? Number((completionTokens / durationS).toFixed(2)) : null,
          context_consumption_fraction:(promptTokens !== null && original.model_max_context_tokens_last_verified)
            ? Number((promptTokens / original.model_max_context_tokens_last_verified).toFixed(4)) : null},
  completion: {response_id:response.id ?? null,finish_reason:choice.finish_reason ?? null,
               text_characters:interpretation.length,reasoning_field_present:hasReasoning},
  controls: {cart_count:sales.nombre_paniers,total_eur_validated:sales.ca_total_eur,
             average_cart_arithmetic_consistent:countCheck,
             products_count:top5.length,top5_descending_by_quantity:top5.every((p,i)=>i===0||top5[i-1].quantity >= p.quantity),
             final_commentary_accepted:commentary===interpretation},
  warnings: warnings,
  unmeasured: ['Exact GPU VRAM usage','GPU utilization','True model inference duration','Independent semantic fact-checking'],
  provenance: 'Model usage from vLLM /v1/chat/completions; financial numbers from the JavaScript calculation nodes.'
};
return [{json:{rapport_ventes:lines.join('\n'),diagnostics:metrics}}];
